<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Discover the Exit</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0; min-height: 100vh; display: grid; place-items: center;
    background: #10151f; color: #edf3ff; font: 15px system-ui, sans-serif;
  }
  main { width: min(680px, 96vw); text-align: center; }
  h1 { margin: 12px 0 8px; font-size: 1.35rem; }
  .bar {
    display: flex; justify-content: center; align-items: center; gap: 18px;
    margin: 10px 0; flex-wrap: wrap;
  }
  .stat { color: #b9c7dc; }
  .stat strong { color: white; }
  button {
    border: 0; border-radius: 7px; padding: 8px 16px; font: inherit;
    font-weight: 700; cursor: pointer; color: #07101e; background: #75d5ff;
  }
  button:hover { background: #b4e8ff; }
  #maze {
    width: min(600px, 94vw); aspect-ratio: 1; margin: auto;
    background: #f7f4e9; border: 5px solid #26364d; border-radius: 5px;
    overflow: hidden;
  }
  canvas { width: 100%; height: 100%; display: block; }
  p { color: #9eafc7; font-size: .86rem; margin: 10px 0 18px; }
</style>
</head>
<body>
<main>
  <h1>24 explorers discover the exit</h1>
  <div class="bar">
    <span class="stat">Completed: <strong id="completed">0 / 24</strong></span>
    <span class="stat">Timer: <strong id="timer">0 ticks</strong></span>
    <button id="reset" type="button">New maze</button>
  </div>
  <div id="maze"><canvas id="canvas" width="600" height="600" aria-label="Maze"></canvas></div>
  <p>Explorers use independent depth-first/Tremaux exploration. Use <code>game.tick(n)</code> to advance.</p>
</main>

<script>
(() => {
  "use strict";

  const ROWS = 15, COLS = 15, BOT_COUNT = 24;
  const canvas = document.getElementById("canvas");
  const ctx = canvas.getContext("2d");
  const completedEl = document.getElementById("completed");
  const timerEl = document.getElementById("timer");
  const directions = [
    { dr: -1, dc: 0, name: "n", opposite: "s" },
    { dr: 0, dc: 1, name: "e", opposite: "w" },
    { dr: 1, dc: 0, name: "s", opposite: "n" },
    { dr: 0, dc: -1, name: "w", opposite: "e" }
  ];

  function seededRandom(seed) {
    let state = (Number(seed) >>> 0) || 0x6d2b79f5;
    return () => {
      state += 0x6D2B79F5;
      let t = state;
      t = Math.imul(t ^ t >>> 15, t | 1);
      t ^= t + Math.imul(t ^ t >>> 7, t | 61);
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  function key(r, c) { return r + "," + c; }
  function copyCell(r, c) { return { r, c }; }

  let maze, bots, elapsed, spawn, exit, random, renderQueued = false;

  function makeMaze() {
    maze = Array.from({ length: ROWS }, () =>
      Array.from({ length: COLS }, () => ({ n: true, e: true, s: true, w: true }))
    );
    const seen = new Set([key(0, 0)]);
    const stack = [{ r: 0, c: 0 }];
    while (stack.length) {
      const here = stack[stack.length - 1];
      const options = directions.filter(d => {
        const r = here.r + d.dr, c = here.c + d.dc;
        return r >= 0 && r < ROWS && c >= 0 && c < COLS && !seen.has(key(r, c));
      });
      if (!options.length) { stack.pop(); continue; }
      const d = options[Math.floor(random() * options.length)];
      const nr = here.r + d.dr, nc = here.c + d.dc;
      maze[here.r][here.c][d.name] = false;
      maze[nr][nc][d.opposite] = false;
      seen.add(key(nr, nc));
      stack.push({ r: nr, c: nc });
    }
  }

  function shuffledDirections() {
    const a = directions.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  // A bot only copies wall knowledge for cells it actually occupies.
  function discover(bot, r, c) {
    const k = key(r, c);
    if (!bot.known[k]) bot.known[k] = { ...maze[r][c] };
    return bot.known[k];
  }

  function makeBots() {
    bots = Array.from({ length: BOT_COUNT }, (_, i) => ({
      path: [copyCell(spawn.r, spawn.c)],
      deadEnds: [],
      finishTick: null,
      r: spawn.r, c: spawn.c,
      fromR: spawn.r, fromC: spawn.c,
      stack: [copyCell(spawn.r, spawn.c)],
      visited: new Set([key(spawn.r, spawn.c)]),
      dead: new Set(),
      known: Object.create(null),
      order: shuffledDirections(),
      hue: Math.round((i * 360) / BOT_COUNT),
      movedAt: performance.now()
    }));
  }

  function move(bot, r, c) {
    bot.fromR = bot.r; bot.fromC = bot.c;
    bot.r = r; bot.c = c;
    bot.path.push(copyCell(r, c));
    bot.movedAt = performance.now();
  }

  function exploreOne(bot) {
    if (bot.finishTick !== null) return;
    if (bot.r === exit.r && bot.c === exit.c) {
      bot.finishTick = elapsed;
      return;
    }

    const localWalls = discover(bot, bot.r, bot.c);
    let choice = null;
    for (const d of bot.order) {
      if (localWalls[d.name]) continue;
      const nr = bot.r + d.dr, nc = bot.c + d.dc;
      if (!bot.visited.has(key(nr, nc))) {
        choice = { r: nr, c: nc };
        break;
      }
    }

    if (choice) {
      move(bot, choice.r, choice.c);
      bot.visited.add(key(choice.r, choice.c));
      bot.stack.push(copyCell(choice.r, choice.c));
      if (choice.r === exit.r && choice.c === exit.c) bot.finishTick = elapsed;
      return;
    }

    // Every locally discovered passage from this cell leads to an explored
    // branch. Mark it dead, then return along its single DFS parent edge.
    const hereKey = key(bot.r, bot.c);
    if (!bot.dead.has(hereKey)) {
      bot.dead.add(hereKey);
      bot.deadEnds.push(copyCell(bot.r, bot.c));
    }
    bot.stack.pop();
    if (bot.stack.length) {
      const parent = bot.stack[bot.stack.length - 1];
      move(bot, parent.r, parent.c);
    }
  }

  function updateLabels() {
    const done = bots.filter(b => b.finishTick !== null).length;
    completedEl.textContent = done + " / " + BOT_COUNT;
    timerEl.textContent = elapsed + " tick" + (elapsed === 1 ? "" : "s");
  }

  function draw() {
    renderQueued = false;
    const W = canvas.width, cell = W / COLS;
    ctx.clearRect(0, 0, W, W);
    ctx.fillStyle = "#f7f4e9";
    ctx.fillRect(0, 0, W, W);

    ctx.fillStyle = "#b9f3c1";
    ctx.fillRect(exit.c * cell + 5, exit.r * cell + 5, cell - 10, cell - 10);
    ctx.fillStyle = "#cfe7ff";
    ctx.fillRect(spawn.c * cell + 5, spawn.r * cell + 5, cell - 10, cell - 10);

    ctx.strokeStyle = "#172638";
    ctx.lineWidth = Math.max(2, cell * 0.09);
    ctx.lineCap = "square";
    ctx.beginPath();
    for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
      const x = c * cell, y = r * cell, w = maze[r][c];
      if (w.n) { ctx.moveTo(x, y); ctx.lineTo(x + cell, y); }
      if (w.w) { ctx.moveTo(x, y); ctx.lineTo(x, y + cell); }
      if (r === ROWS - 1 && w.s) { ctx.moveTo(x, y + cell); ctx.lineTo(x + cell, y + cell); }
      if (c === COLS - 1 && w.e) { ctx.moveTo(x + cell, y); ctx.lineTo(x + cell, y + cell); }
    }
    ctx.stroke();

    const now = performance.now();
    for (const bot of bots) {
      const p = Math.min(1, (now - bot.movedAt) / 130);
      const rr = bot.fromR + (bot.r - bot.fromR) * p;
      const cc = bot.fromC + (bot.c - bot.fromC) * p;
      ctx.beginPath();
      ctx.arc((cc + .5) * cell, (rr + .5) * cell, Math.max(4, cell * .16), 0, Math.PI * 2);
      ctx.fillStyle = `hsl(${bot.hue} 82% 43%)`;
      ctx.fill();
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 1;
      ctx.stroke();
    }
    if (bots.some(b => performance.now() - b.movedAt < 130)) requestDraw();
  }

  function requestDraw() {
    if (!renderQueued) {
      renderQueued = true;
      requestAnimationFrame(draw);
    }
  }

  const game = {
    size: { rows: ROWS, cols: COLS },
    get spawn() { return copyCell(spawn.r, spawn.c); },
    get exit() { return copyCell(exit.r, exit.c); },
    get elapsed() { return elapsed; },
    get bots() { return bots; },
    walls(r, c) {
      if (!Number.isInteger(r) || !Number.isInteger(c) || r < 0 || r >= ROWS || c < 0 || c >= COLS) {
        throw new RangeError("Cell outside maze");
      }
      return { ...maze[r][c] };
    },
    reset(seed) {
      const actualSeed = typeof seed === "number" && Number.isFinite(seed)
        ? seed : Math.floor(Math.random() * 4294967296);
      random = seededRandom(actualSeed);
      spawn = { r: 0, c: 0 };
      exit = { r: ROWS - 1, c: COLS - 1 };
      elapsed = 0;
      makeMaze();
      makeBots();
      updateLabels();
      requestDraw();
      return actualSeed;
    },
    tick(n) {
      n = n === undefined ? 1 : Math.floor(Number(n));
      if (!Number.isFinite(n) || n < 0) throw new RangeError("tick count must be a non-negative number");
      for (let i = 0; i < n; i++) {
        if (bots.every(b => b.finishTick !== null)) break;
        elapsed++;
        for (const bot of bots) exploreOne(bot);
      }
      updateLabels();
      requestDraw();
    }
  };

  window.game = game;
  document.getElementById("reset").addEventListener("click", () => game.reset());
  game.reset(20260825);
})();
</script>
</body>
</html>
